{page==='animeSources'&&<><header><div><h1>Video Sources</h1><p>Combine multiple Aniyomi-compatible repositories for Anime, Series and Movies.</p></div></header><section className={'panel anime-status '+(animeEngine?.online?'engine-online':animeEngine?'engine-offline':'')}><div className="engine-row"><div><h2>Video Engine</h2><p>{animeEngine==null?'Not checked yet':animeEngine.online?'✓ Connected to Miwayomi':'✕ Offline — '+animeEngine.baseUrl}</p></div><button onClick={async()=>setAnimeEngine(await window.novelReader.miwayomiStatus())}>Check engine</button></div></section><section className="panel"><div className="engine-row"><div><h2>Extension repositories</h2><p>Enabled repositories are merged into one source catalogue.</p></div><button className="primary" disabled={animeSourceLoading} onClick={async()=>{setAnimeSourceLoading(true);setAnimeNotice(null);try{const repos=animeRepos.filter((x:any)=>x.enabled&&x.url);if(!repos.length)throw Error('Enable at least one repository');await window.novelReader.miwayomiFetch('/api/v1/extensions/repos','POST',{repos:repos.map((x:any)=>x.url)});const settled=await Promise.allSettled(repos.map(async(repo:any)=>{const r=await fetch(repo.url);if(!r.ok)throw Error(repo.name+' HTTP '+r.status);const data=await r.json();const list=Array.isArray(data)?data:(data.extensions||data.plugins||data.items||[]);return list.map((x:any)=>({...x,repoUrl:repo.url,repoName:repo.name}))}));const blocked=/hentai|jav|missav|xvideos|xnxx|myreadingmanga|debrid|nyaa|jable/i;const merged=settled.flatMap((r:any)=>r.status==='fulfilled'?r.value:[]).filter((x:any)=>!blocked.test(String(x.name||x.pkg||'')));const seen=new Set<string>();setAnimeSources(merged.filter((x:any)=>{const k=String(x.pkg||x.package||x.packageName||x.name||'').toLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true}));const failed=settled.filter((r:any)=>r.status==='rejected').length;setAnimeNotice({ok:true,scope:'sources',text:'Loaded '+merged.length+' entries from '+repos.length+' repositories'+(failed?' ('+failed+' repository failed)':'')+'.'})}catch(e:any){setAnimeNotice({ok:false,scope:'sources',text:e.message})}finally{setAnimeSourceLoading(false)}}}>{animeSourceLoading?'Loading…':'Load all sources'}</button></div><div className="repo-list">{animeRepos.map((r:any,i:number)=><div className="repo-row" key={r.url+i}><label><input type="checkbox" checked={!!r.enabled} onChange={e=>{const next=animeRepos.map((x:any,j:number)=>j===i?{...x,enabled:e.target.checked}:x);setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}/><span><b>{r.name}</b><small>{r.url}</small></span></label><button className="removebtn" onClick={()=>{const next=animeRepos.filter((_:any,j:number)=>j!==i);setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}>Remove</button></div>)}</div><div className="repo-add"><input className="repo-input" placeholder="Repository index.min.json URL" value={animeRepoUrl} onChange={e=>setAnimeRepoUrl(e.target.value)}/><button onClick={()=>{const url=animeRepoUrl.trim();if(!url||animeRepos.some((r:any)=>r.url===url))return;const next=[...animeRepos,{name:'Custom repository',url,enabled:true}];setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}>Add repository</button></div>{animeSources.length>0&&<><div className="source-catalog-head"><p><b>{animeSources.length}</b> unique compatible extensions</p><input className="repo-input" placeholder="Filter sources…" value={animeCatalogFilter} onChange={e=>setAnimeCatalogFilter(e.target.value)}/></div><div className="anime-source-list">{animeSources.filter((x:any)=>{const q=animeCatalogFilter.toLowerCase();return !q||String(x.name||x.pkg||'').toLowerCase().includes(q)||String(x.lang||'').toLowerCase().includes(q)||String(x.repoName||'').toLowerCase().includes(q)}).slice(0,160).map((x:any,i:number)=><button className="anime-source-chip" key={(x.pkg||x.name||'source')+i} onClick={()=>installAnimeSource(x)} title={'Repository: '+(x.repoName||'Custom')}>{x.name||x.pkg}{x.lang?' · '+x.lang:''}<small>{x.repoName?' · '+x.repoName:''}</small></button>)}</div></>}{animeNotice&&animeNotice.scope==='sources'&&<div className={'anime-toast '+(animeNotice.ok?'ok':'error')}><NoticeText text={animeNotice.text}/><button onClick={()=>setAnimeNotice(null)}>×</button></div>}</section></>}
